// FUNCTION: BFME2 0x00367F19 size=116 name=?shouldExit@Rva00367F19ExitConditions@@UBE_NPBVStateMachine@@@Z evidence=?:placeholder
Bool GiantBirdExitConditions::shouldExit(const StateMachine *machine) const
{
	StateMachine *stateMachine = const_cast<StateMachine *>(machine);
	if (!stateMachine->getGoalObject())
	{
		if (m_conditionsToConsider & ExitConditions::ATTACK_ExitIfNoUnitFound)
			return true;
		else
			return false;
	}

	if (m_conditionsToConsider & ExitConditions::ATTACK_ExitIfExpiredDuration)
	{
		if (TheGameLogic->getFrame() >= m_attackGiveUpFrame)
			return true;
	}

	if (m_conditionsToConsider & ExitConditions::ATTACK_ExitIfOutsideRadius)
	{
		const Coord3D *goalPos = stateMachine->getGoalObject()->getPosition();
		Real dx = goalPos->x - m_center.x;
		Real dy = goalPos->y - m_center.y;
		if (dy * dy + dx * dx > m_radiusSqr)
			return true;
	}
	return false;
}

